return-response.set-body:
@{
                        return new JObject(
                            new JProperty("status", "VALIDATION_ERROR"),
                            new JProperty("code", "INVALID_ORDER_ID"),
                            new JProperty("message", "orderId path parameter must be 1–50 uppercase alphanumeric characters or hyphens"),
                            new JProperty("correlationId", context.Request.Headers.GetValueOrDefault("X-Correlation-ID", context.RequestId.ToString())),
                            new JProperty("timestamp", DateTime.UtcNow.ToString("yyyy-MM-ddTHH:mm:ssZ"))
                        ).ToString();
                    }

@{
                var orderId = context.Request.MatchedParameters["orderId"];
                return new JObject(
                    new JProperty("orderId", orderId),
                    new JProperty("status", "WMS_ACCEPTED"),
                    new JProperty("wmsOrderId", string.Format("WMS-{0}-DEMO", DateTime.UtcNow.ToString("yyyyMMddHHmm"))),
                    new JProperty("warehouseRef", string.Format("WH-SIN-{0}", orderId)),
                    new JProperty("estimatedReadyDate", DateTime.UtcNow.AddDays(1).ToString("yyyy-MM-dd")),
                    new JProperty("message", "[DEMO] Mock status response — wire to state store for production"),
                    new JProperty("correlationId", context.Request.Headers.GetValueOrDefault("X-Correlation-ID", context.RequestId.ToString())),
                    new JProperty("enqueuedAtUtc", DateTime.UtcNow.AddMinutes(-5).ToString("yyyy-MM-ddTHH:mm:ssZ")),
                    new JProperty("dispatchedAtUtc", DateTime.UtcNow.AddMinutes(-4).ToString("yyyy-MM-ddTHH:mm:ssZ"))
                ).ToString();
            }
